// SPDX-License-Identifier: MIT
pragma solidity 0.8.19;

/// @title VaultWithDynamicFees - A vault with tiered withdrawal fees
/// @notice Fees decrease as lock duration increases. After full lock period, no fee.
contract VaultWithDynamicFees {
    address public immutable owner;
    uint256 public constant MAX_FEE_BPS = 500; // 5%
    uint256 public constant LOCK_DURATION = 30 days;
    uint256 public constant FEE_GRANULARITY = 10000;
    uint256 public totalFees;

    struct Deposit {
        uint256 amount;
        uint256 timestamp;
        uint256 lockEnd;
        bool active;
    }

    mapping(address => Deposit[]) public deposits;
    mapping(address => uint256) public userTotalDeposited;
    mapping(address => uint256) public rewardDebt;

    uint256 public rewardPerShare;
    uint256 public lastRewardBlock;
    uint256 public totalStaked;

    event Deposited(address indexed user, uint256 amount, uint256 index);
    event Withdrawn(address indexed user, uint256 amount, uint256 fee);
    event RewardsHarvested(address indexed user, uint256 amount);

    modifier onlyOwner() {
        require(msg.sender == owner, "not owner");
        _;
    }

    constructor() {
        owner = msg.sender;
        lastRewardBlock = block.number;
    }

    function deposit() external payable {
        require(msg.value > 0, "zero deposit");
        _updateRewards();

        deposits[msg.sender].push(Deposit({
            amount: msg.value,
            timestamp: block.timestamp,
            lockEnd: block.timestamp + LOCK_DURATION,
            active: true
        }));

        userTotalDeposited[msg.sender] += msg.value;
        totalStaked += msg.value;
        rewardDebt[msg.sender] += (msg.value * rewardPerShare) / 1e18;

        emit Deposited(msg.sender, msg.value, deposits[msg.sender].length - 1);
    }

    function _updateRewards() internal {
        if (totalStaked == 0) {
            lastRewardBlock = block.number;
            return;
        }
        uint256 blocks = block.number - lastRewardBlock;
        uint256 reward = blocks * 1e15; // reward rate
        rewardPerShare += (reward * 1e18) / totalStaked;
        lastRewardBlock = block.number;
    }

    /// @notice Calculate fee based on how much of the lock period has elapsed
    /// @dev Fee decreases linearly from MAX_FEE_BPS to 0 over LOCK_DURATION
    function calculateFee(uint256 depositAmount, uint256 depositTimestamp, uint256 lockEnd) public view returns (uint256) {
        if (block.timestamp >= lockEnd) {
            return 0; // No fee after lock period
        }

        uint256 elapsed = block.timestamp - depositTimestamp;
        uint256 totalDuration = lockEnd - depositTimestamp;

        // Linear decrease: fee = MAX_FEE * (remaining / total)
        uint256 remaining = totalDuration - elapsed;
        uint256 fee = (depositAmount * MAX_FEE_BPS * remaining) / (totalDuration * FEE_GRANULARITY);
        return fee;
    }

    /// @notice Withdraw a specific deposit
    function withdraw(uint256 index) external {
        require(index < deposits[msg.sender].length, "invalid index");
        Deposit storage dep = deposits[msg.sender][index];
        require(dep.active, "already withdrawn");

        _updateRewards();

        uint256 amount = dep.amount;
        uint256 fee = calculateFee(amount, dep.timestamp, dep.lockEnd);

        // Mark as withdrawn before external call (CEI)
        dep.active = false;
        dep.amount = 0;
        userTotalDeposited[msg.sender] -= amount;
        totalStaked -= amount;

        uint256 payout = amount - fee;
        totalFees += fee;

        // Update reward debt
        uint256 pending = (amount * rewardPerShare) / 1e18;
        if (pending > rewardDebt[msg.sender]) {
            rewardDebt[msg.sender] = 0;
        } else {
            rewardDebt[msg.sender] -= pending;
        }

        (bool success, ) = payable(msg.sender).call{value: payout}("");
        require(success, "transfer failed");

        emit Withdrawn(msg.sender, payout, fee);
    }

    /// @notice Emergency withdraw - bypasses reward calculation but applies max fee
    function emergencyWithdraw(uint256 index) external {
        require(index < deposits[msg.sender].length, "invalid index");
        Deposit storage dep = deposits[msg.sender][index];
        require(dep.active, "already withdrawn");

        uint256 amount = dep.amount;
        uint256 fee = (amount * MAX_FEE_BPS) / FEE_GRANULARITY;

        dep.active = false;
        dep.amount = 0;
        userTotalDeposited[msg.sender] -= amount;
        totalStaked -= amount;

        uint256 payout = amount - fee;
        totalFees += fee;

        (bool success, ) = payable(msg.sender).call{value: payout}("");
        require(success, "transfer failed");

        emit Withdrawn(msg.sender, payout, fee);
    }

    /// @notice Extend lock period for reduced future fees on next withdrawal
    /// @dev Users can extend their lock to get better fee rates later
    function extendLock(uint256 index, uint256 additionalTime) external {
        require(index < deposits[msg.sender].length, "invalid index");
        Deposit storage dep = deposits[msg.sender][index];
        require(dep.active, "already withdrawn");
        require(additionalTime > 0 && additionalTime <= 365 days, "invalid extension");

        dep.lockEnd += additionalTime;
    }

    /// @notice Harvest accumulated rewards
    function harvest() external {
        _updateRewards();

        uint256 accumulated = (userTotalDeposited[msg.sender] * rewardPerShare) / 1e18;
        uint256 pending;
        if (accumulated > rewardDebt[msg.sender]) {
            pending = accumulated - rewardDebt[msg.sender];
        }
        require(pending > 0, "nothing to harvest");

        rewardDebt[msg.sender] = accumulated;

        (bool success, ) = payable(msg.sender).call{value: pending}("");
        require(success, "transfer failed");

        emit RewardsHarvested(msg.sender, pending);
    }

    /// @notice Owner collects accumulated fees
    function collectFees() external onlyOwner {
        uint256 fees = totalFees;
        require(fees > 0, "no fees");
        totalFees = 0;

        (bool success, ) = payable(owner).call{value: fees}("");
        require(success, "transfer failed");
    }

    /// @notice Split a deposit into two smaller deposits (for partial withdrawal)
    function splitDeposit(uint256 index, uint256 splitAmount) external {
        require(index < deposits[msg.sender].length, "invalid index");
        Deposit storage dep = deposits[msg.sender][index];
        require(dep.active, "already withdrawn");
        require(splitAmount > 0 && splitAmount < dep.amount, "invalid split");

        uint256 originalTimestamp = dep.timestamp;
        uint256 originalLockEnd = dep.lockEnd;

        dep.amount -= splitAmount;

        // New deposit inherits both original timestamp AND original lockEnd
        // This preserves the fee schedule - no gaming possible
        deposits[msg.sender].push(Deposit({
            amount: splitAmount,
            timestamp: originalTimestamp,
            lockEnd: originalLockEnd,
            active: true
        }));
    }

    receive() external payable {
        // Accept ETH for rewards funding
    }
}
